<?php
require_once __DIR__.'/../../includes/staff/feature-tools.php';require_permission('warranty.view');verify_csrf();$pdo=staff_db();feature_table($pdo,'warranties');$staff=current_staff();
if($_SERVER['REQUEST_METHOD']==='POST'){$a=fpost('action');if($a==='warranty'){$pid=fint('project_id');$p=db_one($pdo,'SELECT customer_id FROM projects WHERE id=?',[$pid]);$pdo->prepare('INSERT INTO warranties(warranty_code,project_id,customer_id,starts_on,expires_on,status,coverage_terms,created_by) VALUES(?,?,?,?,?,?,?,?)')->execute([op_code('WAR'),$pid,$p['customer_id'],fpost('starts_on'),fpost('expires_on'),'active',fpost('terms')?:null,$staff['id']]);flash('success','Warranty created.');}elseif($a==='claim'){$wa=db_one($pdo,'SELECT project_id,customer_id FROM warranties WHERE id=?',[fint('warranty_id')]);if(!$wa){flash('error','Warranty not found.');staff_redirect('staff/pages/warranty.php');}$pdo->prepare('INSERT INTO warranty_claims(claim_code,warranty_id,project_id,customer_id,issue_title,issue_description,status,priority) VALUES(?,?,?,?,?,?,?,?)')->execute([op_code('CLM'),fint('warranty_id'),$wa['project_id'],$wa['customer_id'],fpost('title'),fpost('description'),'new',fpost('priority','normal')]);flash('success','Warranty claim opened.');}staff_redirect('staff/pages/warranty.php');}
$projects=project_options($pdo);$w=db_rows($pdo,'SELECT w.*,p.project_code,p.name project_name,c.name customer_name FROM warranties w JOIN projects p ON p.id=w.project_id JOIN customers c ON c.id=w.customer_id ORDER BY w.expires_on');$claims=db_rows($pdo,'SELECT c.*,w.warranty_code FROM warranty_claims c JOIN warranties w ON w.id=c.warranty_id ORDER BY c.created_at DESC');$pageTitle='Warranty & After-Sales';require __DIR__.'/../../includes/staff/header.php';module_head('After-Sales','Warranty & Service','Keep completed projects connected to warranty coverage and service claims.');?>
<div class="split-grid"><section class="staff-panel"><h2>Create warranty</h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="warranty"><label>Project<select name="project_id"><?php foreach($projects as $p):?><option value="<?=$p['id']?>"><?=h($p['project_code'].' · '.$p['name'])?></option><?php endforeach?></select></label><div class="two"><label>Starts<input type="date" name="starts_on" required></label><label>Expires<input type="date" name="expires_on" required></label></div><label>Terms<textarea name="terms"></textarea></label><button class="btn primary">Create warranty</button></form></section><section class="staff-panel"><h2>Open claim</h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="claim"><label>Warranty<select name="warranty_id"><?php foreach($w as $x):?><option value="<?=$x['id']?>"><?=h($x['warranty_code'].' · '.$x['customer_name'])?></option><?php endforeach?></select></label><label>Issue<input name="title" required></label><label>Description<textarea name="description"></textarea></label><label>Priority<select name="priority"><option>normal</option><option>high</option><option>urgent</option><option>low</option></select></label><button class="btn">Create claim</button></form></section></div><section class="staff-panel table-panel"><table><thead><tr><th>Warranty</th><th>Project</th><th>Customer</th><th>Coverage</th><th>Status</th></tr></thead><tbody><?php foreach($w as $x):?><tr><td><b><?=h($x['warranty_code'])?></b></td><td><?=h($x['project_code'].' · '.$x['project_name'])?></td><td><?=h($x['customer_name'])?></td><td><?=h($x['starts_on'].' → '.$x['expires_on'])?></td><td><span class="pill"><?=h($x['status'])?></span></td></tr><?php endforeach?></tbody></table></section><section class="staff-panel"><h2>Claims</h2><?php foreach($claims as $c):?><div class="board-card"><b><?=h($c['claim_code'].' · '.$c['issue_title'])?></b><p><?=h($c['issue_description']?:'')?></p><small><?=h($c['warranty_code'].' · '.$c['priority'].' · '.$c['status'])?></small></div><?php endforeach?></section><?php module_end();require __DIR__.'/../../includes/staff/footer.php';?>